-- Ten researched, globally diverse vegan and vegetarian recipes.
-- Nutrition values are per-serving planning estimates based on the gram weights in
-- each formulation and USDA FoodData Central reference foods. They are deliberately
-- labelled as estimates in their derivation metadata.

with recipes(data) as (
  values
  ($json${
    "id":"recipe_world_egyptian_taameya",
    "name_common":"Egyptian Ta'ameya with Tomato-Cucumber Salad",
    "category":"meal","category_sub":["Lunch","Dinner"],"meal_slot":"lunch",
    "cuisine":"Egyptian","origin":"Egypt","language":"en","difficulty":"medium","prep_time":"25 min + soak","cook_time":"20 min","servings":4,"serving_size":"4 patties + salad",
    "description":"Emerald-centred fava-bean patties fragrant with coriander, parsley, cumin, and leek, served with a sharp tomato-cucumber salad. Air-frying or baking keeps the crust crisp while using far less oil than deep-frying.",
    "description_simple":"Crisp Egyptian fava-bean patties packed with fresh herbs, with a bright tomato-cucumber salad.",
    "description_technical":"A legume-forward main combining fava-bean protein and fibre with vitamin C-rich raw vegetables. Nutrition assumes 15 g total retained oil across four servings.",
    "ingredients":[{"name":"Dried split fava beans","amount_g":300,"unit":"g","note":"soaked 12 hours and drained"},{"name":"Leek","amount_g":100,"unit":"g","note":"chopped"},{"name":"Fresh coriander","amount_g":45,"unit":"g"},{"name":"Flat-leaf parsley","amount_g":35,"unit":"g"},{"name":"Garlic","amount_g":12,"unit":"g"},{"name":"Ground cumin","amount_g":5,"unit":"g"},{"name":"Ground coriander","amount_g":5,"unit":"g"},{"name":"Sesame seeds","amount_g":24,"unit":"g"},{"name":"Olive oil","amount_g":15,"unit":"g"},{"name":"Tomato","amount_g":300,"unit":"g","note":"diced"},{"name":"Cucumber","amount_g":240,"unit":"g","note":"diced"},{"name":"Lemon juice","amount_g":45,"unit":"g"},{"name":"Sea salt","amount_g":5,"unit":"g"}],
    "instructions":[{"text":"Drain the soaked fava beans very well. Pulse with leek, herbs, garlic, cumin, coriander, and salt until finely minced but not wet or puréed."},{"text":"Rest the mixture for 15 minutes, then shape 16 compact patties. Press sesame seeds onto both faces."},{"text":"Brush with the olive oil and air-fry at 200°C for 12–15 minutes, turning once, or bake at 220°C for 18–20 minutes until deeply crisp."},{"text":"Toss tomato and cucumber with lemon juice and a pinch of salt. Serve four hot patties per person with the salad."}],
    "nutrition_per_serving":{"energy_kcal":390,"protein_g":19,"carbohydrates_g":55,"fiber_g":14,"fats_g":11,"saturated_fat_g":1.5,"sodium_mg":430,"_derivation":{"method":"ingredient-weight estimate","source":"USDA FoodData Central reference foods","basis":"prepared recipe / 4 servings","needs_curation":false}},
    "health_score":92,"taste_profile":{"taste":{"sweet":2,"sour":4,"salty":3,"bitter":1,"umami":4,"spicy":2},"texture":{"crispy":5,"creamy":3,"crunchy":3}},
    "dietary_info":{"vegan":true,"vegetarian":true,"egg_free":true,"dairy_free":true,"gluten_free":true,"contains_sesame":true,"contains_nut":false,"contains_soy":false},"allergens":["sesame","fava beans (avoid with G6PD deficiency)"],
    "tags":["world-class","plant-forward","high-protein","high-fibre","egyptian","vegan"],"image_url":"https://healthscan.live/images/recipes/world/egyptian-taameya.webp","image_primary_url":"https://healthscan.live/images/recipes/world/egyptian-taameya.webp"
  }$json$::jsonb),
  ($json${
    "id":"recipe_world_ethiopian_misir_wat","name_common":"Ethiopian Misir Wat","category":"meal","category_sub":["Dinner","One-Pot","Curry"],"meal_slot":"dinner","cuisine":"Ethiopian","origin":"Ethiopia","language":"en","difficulty":"easy","prep_time":"15 min","cook_time":"40 min","servings":4,"serving_size":"about 400 g",
    "description":"Red lentils melt into a brick-red stew layered with slowly cooked onion, berbere, ginger, garlic, and tomato. Lemon and fresh coriander lift the deep, warm spice at the table.","description_simple":"A rich Ethiopian red-lentil stew with berbere, tomato, ginger, and lemon.","description_technical":"High-fibre lentils provide plant protein and iron; tomato and lemon contribute vitamin C. Berbere heat varies, so start with less and build.",
    "ingredients":[{"name":"Red lentils","amount_g":320,"unit":"g","note":"rinsed"},{"name":"Red onion","amount_g":300,"unit":"g","note":"finely diced"},{"name":"Tomato","amount_g":400,"unit":"g","note":"crushed"},{"name":"Garlic","amount_g":18,"unit":"g","note":"minced"},{"name":"Fresh ginger","amount_g":20,"unit":"g","note":"grated"},{"name":"Berbere spice","amount_g":18,"unit":"g"},{"name":"Olive oil","amount_g":30,"unit":"g"},{"name":"Water","amount_g":900,"unit":"ml"},{"name":"Lemon juice","amount_g":40,"unit":"g"},{"name":"Sea salt","amount_g":5,"unit":"g"}],
    "instructions":[{"text":"Cook the onion in a heavy pot over medium-low heat for 10 minutes, stirring often, until soft and golden at the edges."},{"text":"Add oil, garlic, ginger, and berbere. Cook for 60 seconds until fragrant, taking care not to scorch the spices."},{"text":"Stir in tomato, lentils, and water. Simmer partly covered for 25–30 minutes, stirring near the end, until velvety."},{"text":"Season with salt and lemon. Rest five minutes before serving with injera or a whole grain."}],
    "nutrition_per_serving":{"energy_kcal":430,"protein_g":22,"carbohydrates_g":66,"fiber_g":18,"fats_g":9,"saturated_fat_g":1.3,"sodium_mg":440,"_derivation":{"method":"ingredient-weight estimate","source":"USDA FoodData Central reference foods","basis":"prepared recipe / 4 servings","needs_curation":false}},
    "health_score":95,"taste_profile":{"taste":{"sweet":2,"sour":3,"salty":3,"bitter":1,"umami":5,"spicy":5},"texture":{"creamy":5,"smooth":4}},"dietary_info":{"vegan":true,"vegetarian":true,"egg_free":true,"dairy_free":true,"gluten_free":true,"contains_nut":false,"contains_soy":false,"contains_sesame":false},"allergens":[],"tags":["world-class","plant-forward","high-protein","high-fibre","ethiopian","vegan"],"image_url":"https://healthscan.live/images/recipes/world/ethiopian-misir-wat.webp","image_primary_url":"https://healthscan.live/images/recipes/world/ethiopian-misir-wat.webp"
  }$json$::jsonb),
  ($json${
    "id":"recipe_world_levantine_mujaddara","name_common":"Levantine Mujaddara","category":"meal","category_sub":["Dinner","One-Pot","Bowl"],"meal_slot":"dinner","cuisine":"Levantine","origin":"Levant","language":"en","difficulty":"easy","prep_time":"15 min","cook_time":"50 min","servings":4,"serving_size":"about 390 g",
    "description":"Earthy lentils and brown basmati rice are crowned with deeply caramelised onions, toasted cumin, parsley, and lemon. The contrast between tender grains and crisp-edged onions makes a humble pantry dish feel luxurious.","description_simple":"Lentils and brown rice with cumin, lemon, herbs, and deeply caramelised onions.","description_technical":"A complementary legume-and-grain main with substantial fibre. Browning the onions slowly creates sweetness and savoury complexity without added sugar.",
    "ingredients":[{"name":"Brown lentils","amount_g":260,"unit":"g","note":"rinsed"},{"name":"Brown basmati rice","amount_g":220,"unit":"g","note":"rinsed"},{"name":"Yellow onions","amount_g":600,"unit":"g","note":"thinly sliced"},{"name":"Olive oil","amount_g":45,"unit":"g"},{"name":"Ground cumin","amount_g":7,"unit":"g"},{"name":"Ground coriander","amount_g":4,"unit":"g"},{"name":"Water","amount_g":1200,"unit":"ml"},{"name":"Lemon juice","amount_g":45,"unit":"g"},{"name":"Flat-leaf parsley","amount_g":30,"unit":"g"},{"name":"Sea salt","amount_g":5,"unit":"g"}],
    "instructions":[{"text":"Cook the onions with two-thirds of the oil and a pinch of salt over medium-low heat for 25–30 minutes, stirring, until mahogany at the edges. Reserve half."},{"text":"Add cumin and coriander to the pot, toast for 30 seconds, then add lentils and water. Simmer for 15 minutes."},{"text":"Stir in rice and remaining salt. Cover and cook gently for 25–30 minutes until both are tender; add a splash of water only if needed."},{"text":"Fold in lemon and parsley. Top with the reserved onions and remaining olive oil."}],
    "nutrition_per_serving":{"energy_kcal":535,"protein_g":21,"carbohydrates_g":91,"fiber_g":19,"fats_g":13,"saturated_fat_g":1.9,"sodium_mg":440,"_derivation":{"method":"ingredient-weight estimate","source":"USDA FoodData Central reference foods","basis":"prepared recipe / 4 servings","needs_curation":false}},
    "health_score":93,"taste_profile":{"taste":{"sweet":4,"sour":3,"salty":3,"bitter":1,"umami":5,"spicy":2},"texture":{"chewy":3,"crispy":3,"creamy":2}},"dietary_info":{"vegan":true,"vegetarian":true,"egg_free":true,"dairy_free":true,"gluten_free":true,"contains_nut":false,"contains_soy":false,"contains_sesame":false},"allergens":[],"tags":["world-class","plant-forward","high-protein","high-fibre","levantine","vegan"],"image_url":"https://healthscan.live/images/recipes/world/levantine-mujaddara.webp","image_primary_url":"https://healthscan.live/images/recipes/world/levantine-mujaddara.webp"
  }$json$::jsonb),
  ($json${
    "id":"recipe_world_ethiopian_shiro_wat","name_common":"Ethiopian Shiro Wat","category":"meal","category_sub":["Dinner","One-Pot","Curry"],"meal_slot":"dinner","cuisine":"Ethiopian and Eritrean","origin":"Ethiopia and Eritrea","language":"en","difficulty":"easy","prep_time":"10 min","cook_time":"30 min","servings":4,"serving_size":"about 350 g",
    "description":"Roasted chickpea flour is whisked into a glossy onion-tomato sauce scented with berbere, garlic, and ginger. The result is silky, warming, and intensely savoury despite its short ingredient list.","description_simple":"A silky Ethiopian and Eritrean chickpea-flour stew with berbere, onion, and tomato.","description_technical":"Chickpea flour supplies protein, fibre, folate, and iron. Continuous whisking prevents lumps and gives shiro its characteristic smooth texture.",
    "ingredients":[{"name":"Roasted chickpea flour","amount_g":240,"unit":"g"},{"name":"Red onion","amount_g":300,"unit":"g","note":"finely diced"},{"name":"Tomato","amount_g":300,"unit":"g","note":"crushed"},{"name":"Garlic","amount_g":15,"unit":"g"},{"name":"Fresh ginger","amount_g":15,"unit":"g"},{"name":"Berbere spice","amount_g":14,"unit":"g"},{"name":"Olive oil","amount_g":30,"unit":"g"},{"name":"Water","amount_g":1100,"unit":"ml"},{"name":"Sea salt","amount_g":5,"unit":"g"}],
    "instructions":[{"text":"Cook the onion in a heavy saucepan over medium-low heat for 8–10 minutes until very soft."},{"text":"Add oil, garlic, ginger, and berbere; cook for one minute. Add tomato and simmer five minutes."},{"text":"Whisk chickpea flour with 400 ml cool water until smooth. Whisk it into the pot, then gradually whisk in the remaining water."},{"text":"Simmer gently for 12–15 minutes, stirring often, until glossy and spoon-coating. Season and serve hot."}],
    "nutrition_per_serving":{"energy_kcal":385,"protein_g":16,"carbohydrates_g":48,"fiber_g":12,"fats_g":13,"saturated_fat_g":1.8,"sodium_mg":450,"_derivation":{"method":"ingredient-weight estimate","source":"USDA FoodData Central reference foods","basis":"prepared recipe / 4 servings","needs_curation":false}},
    "health_score":91,"taste_profile":{"taste":{"sweet":2,"sour":2,"salty":3,"bitter":1,"umami":5,"spicy":5},"texture":{"creamy":5,"smooth":5}},"dietary_info":{"vegan":true,"vegetarian":true,"egg_free":true,"dairy_free":true,"gluten_free":true,"contains_nut":false,"contains_soy":false,"contains_sesame":false},"allergens":[],"tags":["world-class","plant-forward","high-protein","high-fibre","ethiopian","eritrean","vegan"],"image_url":"https://healthscan.live/images/recipes/world/ethiopian-shiro-wat.webp","image_primary_url":"https://healthscan.live/images/recipes/world/ethiopian-shiro-wat.webp"
  }$json$::jsonb),
  ($json${
    "id":"recipe_world_georgian_badrijani","name_common":"Georgian Badrijani Nigvzit","category":"meal","category_sub":["Lunch"],"meal_slot":"appetizer","cuisine":"Georgian","origin":"Georgia","language":"en","difficulty":"medium","prep_time":"30 min","cook_time":"25 min","servings":4,"serving_size":"3 rolls",
    "description":"Smoky ribbons of roasted eggplant wrap a punchy walnut, garlic, coriander, and fenugreek filling, finished with pomegranate and herbs. Creamy, tart, aromatic, and jewel-like on the plate.","description_simple":"Roasted eggplant rolls filled with spiced walnut-garlic cream and pomegranate.","description_technical":"Walnuts contribute unsaturated fat and alpha-linolenic acid; eggplant and pomegranate add fibre and varied plant compounds. Portioning moderates energy density.",
    "ingredients":[{"name":"Eggplant","amount_g":800,"unit":"g","note":"cut lengthwise into 12 thin slices"},{"name":"Walnuts","amount_g":180,"unit":"g"},{"name":"Garlic","amount_g":12,"unit":"g"},{"name":"Ground coriander","amount_g":4,"unit":"g"},{"name":"Blue fenugreek or fenugreek","amount_g":2,"unit":"g"},{"name":"Red wine vinegar","amount_g":25,"unit":"g"},{"name":"Water","amount_g":100,"unit":"ml"},{"name":"Olive oil","amount_g":25,"unit":"g"},{"name":"Pomegranate arils","amount_g":80,"unit":"g"},{"name":"Fresh coriander","amount_g":20,"unit":"g"},{"name":"Sea salt","amount_g":4,"unit":"g"}],
    "instructions":[{"text":"Salt the eggplant lightly and rest 15 minutes. Blot dry, brush with oil, and roast at 220°C for 18–22 minutes, turning once, until flexible and browned."},{"text":"Process walnuts, garlic, spices, vinegar, salt, and enough water to make a thick, textured cream."},{"text":"Spread a heaped tablespoon of filling over each cooled eggplant slice and roll from the narrow end."},{"text":"Chill for 20 minutes if time allows. Finish with pomegranate and coriander."}],
    "nutrition_per_serving":{"energy_kcal":370,"protein_g":9,"carbohydrates_g":25,"fiber_g":9,"fats_g":29,"saturated_fat_g":3.1,"sodium_mg":350,"_derivation":{"method":"ingredient-weight estimate","source":"USDA FoodData Central reference foods","basis":"prepared recipe / 4 servings","needs_curation":false}},
    "health_score":86,"taste_profile":{"taste":{"sweet":2,"sour":4,"salty":3,"bitter":2,"umami":5,"spicy":2},"texture":{"creamy":5,"chewy":3,"crunchy":2}},"dietary_info":{"vegan":true,"vegetarian":true,"egg_free":true,"dairy_free":true,"gluten_free":true,"contains_nut":true,"contains_soy":false,"contains_sesame":false},"allergens":["walnuts"],"tags":["world-class","plant-forward","georgian","vegan","walnuts"],"image_url":"https://healthscan.live/images/recipes/world/georgian-badrijani.webp","image_primary_url":"https://healthscan.live/images/recipes/world/georgian-badrijani.webp"
  }$json$::jsonb),
  ($json${
    "id":"recipe_world_greek_yemista","name_common":"Greek Lentil Yemista","category":"meal","category_sub":["Dinner","Baked goods"],"meal_slot":"dinner","cuisine":"Greek","origin":"Greece","language":"en","difficulty":"medium","prep_time":"30 min","cook_time":"75 min","servings":4,"serving_size":"2 stuffed vegetables",
    "description":"Tomatoes and peppers roast around a filling of short-grain rice, lentils, mint, parsley, currants, and pine nuts. The vegetable juices season the rice from within while the tops blister and caramelise.","description_simple":"Roasted tomatoes and peppers stuffed with herbed rice, lentils, currants, and pine nuts.","description_technical":"Adding lentils to a traditional rice filling improves protein and fibre while preserving the fresh herb and olive-oil character of the dish.",
    "ingredients":[{"name":"Large tomatoes","amount_g":800,"unit":"g","note":"4, tops reserved"},{"name":"Bell peppers","amount_g":600,"unit":"g","note":"4, tops reserved"},{"name":"Cooked brown lentils","amount_g":300,"unit":"g"},{"name":"Short-grain brown rice","amount_g":180,"unit":"g"},{"name":"Red onion","amount_g":180,"unit":"g"},{"name":"Zucchini","amount_g":200,"unit":"g","note":"grated"},{"name":"Pine nuts","amount_g":35,"unit":"g"},{"name":"Currants","amount_g":30,"unit":"g"},{"name":"Fresh mint","amount_g":20,"unit":"g"},{"name":"Flat-leaf parsley","amount_g":30,"unit":"g"},{"name":"Olive oil","amount_g":40,"unit":"g"},{"name":"Sea salt","amount_g":5,"unit":"g"}],
    "instructions":[{"text":"Cut lids from the tomatoes and peppers. Scoop out the tomato flesh, chop it, and keep all juices. Remove pepper seeds."},{"text":"Cook onion in half the oil for five minutes. Add zucchini, rice, chopped tomato, and 250 ml water; simmer eight minutes."},{"text":"Fold in lentils, pine nuts, currants, mint, parsley, and salt. Fill each vegetable three-quarters full and replace the lids."},{"text":"Pack into a baking dish, drizzle with remaining oil, add 150 ml water, and bake at 190°C for 65–75 minutes. Rest 15 minutes."}],
    "nutrition_per_serving":{"energy_kcal":465,"protein_g":15,"carbohydrates_g":67,"fiber_g":13,"fats_g":18,"saturated_fat_g":2.4,"sodium_mg":440,"_derivation":{"method":"ingredient-weight estimate","source":"USDA FoodData Central reference foods","basis":"prepared recipe / 4 servings","needs_curation":false}},
    "health_score":94,"taste_profile":{"taste":{"sweet":4,"sour":3,"salty":3,"bitter":1,"umami":5,"spicy":1},"texture":{"juicy":5,"chewy":3,"crunchy":2}},"dietary_info":{"vegan":true,"vegetarian":true,"egg_free":true,"dairy_free":true,"gluten_free":true,"contains_nut":true,"contains_soy":false,"contains_sesame":false},"allergens":["pine nuts"],"tags":["world-class","plant-forward","high-fibre","greek","vegan"],"image_url":"https://healthscan.live/images/recipes/world/greek-lentil-yemista.webp","image_primary_url":"https://healthscan.live/images/recipes/world/greek-lentil-yemista.webp"
  }$json$::jsonb),
  ($json${
    "id":"recipe_world_turkish_piyaz","name_common":"Antalya-Style Piyaz","category":"salad","category_sub":["Protein Salad"],"meal_slot":"lunch","cuisine":"Turkish","origin":"Antalya, Türkiye","language":"en","difficulty":"easy","prep_time":"20 min","cook_time":"5 min","servings":4,"serving_size":"about 350 g",
    "description":"Creamy white beans meet a lemony tahini-garlic dressing, ripe tomato, red onion, parsley, and sumac. It eats like a full meal: fresh and bright first, nutty and savoury underneath.","description_simple":"White-bean salad with tahini, lemon, tomato, red onion, parsley, and sumac.","description_technical":"Beans provide protein, fibre, potassium, and iron; lemon and tomato add acidity and vitamin C. Tahini adds sesame allergen and energy-dense unsaturated fats.",
    "ingredients":[{"name":"Cooked white beans","amount_g":800,"unit":"g","note":"drained and rinsed"},{"name":"Tomato","amount_g":400,"unit":"g","note":"cut into wedges"},{"name":"Red onion","amount_g":140,"unit":"g","note":"thinly sliced"},{"name":"Tahini","amount_g":90,"unit":"g"},{"name":"Lemon juice","amount_g":90,"unit":"g"},{"name":"Garlic","amount_g":10,"unit":"g"},{"name":"Flat-leaf parsley","amount_g":40,"unit":"g"},{"name":"Olive oil","amount_g":20,"unit":"g"},{"name":"Sumac","amount_g":5,"unit":"g"},{"name":"Sea salt","amount_g":4,"unit":"g"}],
    "instructions":[{"text":"Whisk tahini, lemon, garlic, salt, and 60–100 ml cool water until pale and pourable."},{"text":"Rinse the sliced onion under cool water and squeeze dry to soften its bite."},{"text":"Fold beans with half the dressing and let stand ten minutes."},{"text":"Arrange tomato and onion over the beans. Spoon over remaining dressing; finish with parsley, sumac, and olive oil."}],
    "nutrition_per_serving":{"energy_kcal":455,"protein_g":21,"carbohydrates_g":58,"fiber_g":16,"fats_g":18,"saturated_fat_g":2.5,"sodium_mg":420,"_derivation":{"method":"ingredient-weight estimate","source":"USDA FoodData Central reference foods","basis":"prepared recipe / 4 servings","needs_curation":false}},
    "health_score":94,"taste_profile":{"taste":{"sweet":2,"sour":5,"salty":3,"bitter":1,"umami":4,"spicy":1},"texture":{"creamy":5,"juicy":4,"crunchy":3}},"dietary_info":{"vegan":true,"vegetarian":true,"egg_free":true,"dairy_free":true,"gluten_free":true,"contains_nut":false,"contains_soy":false,"contains_sesame":true},"allergens":["sesame"],"tags":["world-class","plant-forward","high-protein","high-fibre","turkish","vegan"],"image_url":"https://healthscan.live/images/recipes/world/turkish-antalya-piyaz.webp","image_primary_url":"https://healthscan.live/images/recipes/world/turkish-antalya-piyaz.webp"
  }$json$::jsonb),
  ($json${
    "id":"recipe_world_italian_pasta_e_ceci","name_common":"Roman Pasta e Ceci","category":"meal","category_sub":["Dinner","One-Pot"],"meal_slot":"dinner","cuisine":"Italian","origin":"Rome, Italy","language":"en","difficulty":"easy","prep_time":"15 min","cook_time":"35 min","servings":4,"serving_size":"about 450 g",
    "description":"Chickpeas and small whole-wheat pasta simmer together with tomato, rosemary, garlic, and lemon until the broth turns naturally creamy. Crisp rosemary chickpeas on top bring contrast without dairy.","description_simple":"A creamy one-pot Roman chickpea and whole-wheat pasta with tomato, rosemary, and lemon.","description_technical":"Chickpeas and whole-grain pasta raise protein and fibre. Mashing some chickpeas thickens the broth through starch rather than cream.",
    "ingredients":[{"name":"Cooked chickpeas","amount_g":700,"unit":"g","note":"drained, liquid reserved if unsalted"},{"name":"Whole-wheat ditalini","amount_g":280,"unit":"g"},{"name":"Crushed tomato","amount_g":350,"unit":"g"},{"name":"Yellow onion","amount_g":160,"unit":"g"},{"name":"Carrot","amount_g":120,"unit":"g"},{"name":"Celery","amount_g":100,"unit":"g"},{"name":"Garlic","amount_g":15,"unit":"g"},{"name":"Olive oil","amount_g":35,"unit":"g"},{"name":"Fresh rosemary","amount_g":6,"unit":"g"},{"name":"Lemon juice","amount_g":35,"unit":"g"},{"name":"Water or unsalted stock","amount_g":1000,"unit":"ml"},{"name":"Sea salt","amount_g":5,"unit":"g"}],
    "instructions":[{"text":"Cook onion, carrot, and celery in two-thirds of the oil for eight minutes. Add garlic and rosemary for 30 seconds."},{"text":"Add tomato, chickpeas, and water. Mash about one-quarter of the chickpeas against the pot and simmer ten minutes."},{"text":"Add pasta and cook in the broth until al dente, stirring often. Add hot water as needed to keep it loose and spoonable."},{"text":"Finish with lemon and remaining oil. Rest five minutes; the broth will thicken."}],
    "nutrition_per_serving":{"energy_kcal":575,"protein_g":23,"carbohydrates_g":94,"fiber_g":17,"fats_g":14,"saturated_fat_g":2,"sodium_mg":470,"_derivation":{"method":"ingredient-weight estimate","source":"USDA FoodData Central reference foods","basis":"prepared recipe / 4 servings","needs_curation":false}},
    "health_score":91,"taste_profile":{"taste":{"sweet":2,"sour":3,"salty":3,"bitter":1,"umami":5,"spicy":1},"texture":{"creamy":5,"chewy":4,"crispy":1}},"dietary_info":{"vegan":true,"vegetarian":true,"egg_free":true,"dairy_free":true,"gluten_free":false,"contains_gluten":true,"contains_nut":false,"contains_soy":false,"contains_sesame":false},"allergens":["wheat"],"tags":["world-class","plant-forward","high-protein","high-fibre","italian","vegan"],"image_url":"https://healthscan.live/images/recipes/world/roman-pasta-e-ceci.webp","image_primary_url":"https://healthscan.live/images/recipes/world/roman-pasta-e-ceci.webp"
  }$json$::jsonb),
  ($json${
    "id":"recipe_world_tunisian_shakshuka","name_common":"Tunisian-Style Shakshuka","category":"meal","category_sub":["Breakfast","Brunch","One-Pot"],"meal_slot":"breakfast","cuisine":"Tunisian and North African","origin":"Tunisia","language":"en","difficulty":"easy","prep_time":"15 min","cook_time":"30 min","servings":4,"serving_size":"2 eggs + sauce",
    "description":"Eggs poach gently in a thick harissa tomato-pepper sauce scented with cumin and coriander. Runny yolks enrich the smoky, tangy sauce while herbs and lemon keep it bright.","description_simple":"Eggs poached in a smoky harissa tomato and pepper sauce with herbs and lemon.","description_technical":"Eggs provide complete protein, choline, and vitamin B12; tomatoes and peppers contribute vitamin C and carotenoids. Sodium depends strongly on harissa brand.",
    "ingredients":[{"name":"Eggs","amount_g":400,"unit":"g","note":"8 large"},{"name":"Crushed tomato","amount_g":800,"unit":"g"},{"name":"Red bell pepper","amount_g":300,"unit":"g","note":"diced"},{"name":"Yellow onion","amount_g":200,"unit":"g","note":"diced"},{"name":"Garlic","amount_g":15,"unit":"g"},{"name":"Harissa paste","amount_g":35,"unit":"g"},{"name":"Olive oil","amount_g":30,"unit":"g"},{"name":"Ground cumin","amount_g":5,"unit":"g"},{"name":"Ground coriander","amount_g":4,"unit":"g"},{"name":"Lemon juice","amount_g":30,"unit":"g"},{"name":"Fresh coriander","amount_g":25,"unit":"g"},{"name":"Sea salt","amount_g":4,"unit":"g"}],
    "instructions":[{"text":"Cook onion and pepper in oil over medium heat for eight minutes until soft and lightly browned."},{"text":"Add garlic, cumin, coriander, and harissa; cook one minute. Add tomato and simmer uncovered for 12–15 minutes until thick."},{"text":"Make eight wells, crack in the eggs, cover, and cook gently for 5–8 minutes until whites set and yolks remain soft."},{"text":"Finish with lemon and coriander. Serve immediately."}],
    "nutrition_per_serving":{"energy_kcal":335,"protein_g":18,"carbohydrates_g":24,"fiber_g":7,"fats_g":20,"saturated_fat_g":5,"sodium_mg":610,"_derivation":{"method":"ingredient-weight estimate","source":"USDA FoodData Central reference foods","basis":"prepared recipe / 4 servings","needs_curation":false}},
