), normalized as (
  select
    data,
    data->>'id' as id
  from recipes
)
insert into public.catalog_recipes (
  id, name_common, category, category_sub, meal_slot, cuisine, origin, language,
  difficulty, prep_time, cook_time, servings, serving_size, description,
  description_simple, description_technical, ingredients, instructions,
  nutrition_per_serving, health_score, taste_profile, dietary_info, allergens,
  tags, image_url, image_primary_url, is_primary, scannable, updated_at
)
select
  id,
  data->>'name_common', data->>'category', data->'category_sub', data->>'meal_slot',
  data->>'cuisine', data->>'origin', data->>'language', data->>'difficulty',
  data->>'prep_time', data->>'cook_time', (data->>'servings')::integer,
  data->>'serving_size', data->>'description', data->>'description_simple',
  data->>'description_technical', data->'ingredients', data->'instructions',
  data->'nutrition_per_serving', (data->>'health_score')::numeric,
  data->'taste_profile', data->'dietary_info',
  array(select jsonb_array_elements_text(data->'allergens')),
  array(select jsonb_array_elements_text(data->'tags')),
  data->>'image_url', data->>'image_primary_url', true, true, now()
from normalized
on conflict (id) do update set
  name_common = excluded.name_common,
  category = excluded.category,
  category_sub = excluded.category_sub,
  meal_slot = excluded.meal_slot,
  cuisine = excluded.cuisine,
  origin = excluded.origin,
  language = excluded.language,
  difficulty = excluded.difficulty,
  prep_time = excluded.prep_time,
  cook_time = excluded.cook_time,
  servings = excluded.servings,
  serving_size = excluded.serving_size,
  description = excluded.description,
  description_simple = excluded.description_simple,
  description_technical = excluded.description_technical,
  ingredients = excluded.ingredients,
  instructions = excluded.instructions,
  nutrition_per_serving = excluded.nutrition_per_serving,
  health_score = excluded.health_score,
  taste_profile = excluded.taste_profile,
  dietary_info = excluded.dietary_info,
  allergens = excluded.allergens,
  tags = excluded.tags,
  image_url = excluded.image_url,
  image_primary_url = excluded.image_primary_url,
  is_primary = excluded.is_primary,
  scannable = excluded.scannable,
  updated_at = now();

notify pgrst, 'reload schema';
